import{_ as e,c as t,o as i,a4 as s}from"./chunks/framework.ttppV29E.js";const g=JSON.parse('{"title":"Open ID Connect Bearer Token","description":"","frontmatter":{},"headers":[],"relativePath":"docs/endpoint-authentication/openid-connect-bearer-token.md","filePath":"docs/endpoint-authentication/openid-connect-bearer-token.md","lastUpdated":1789388022000}'),a={name:"docs/endpoint-authentication/openid-connect-bearer-token.md"},n=s(`<h1 id="open-id-connect-bearer-token" tabindex="-1">Open ID Connect Bearer Token <a class="header-anchor" href="#open-id-connect-bearer-token" aria-label="Permalink to &quot;Open ID Connect Bearer Token&quot;">​</a></h1><p>Endpoints can require an <strong>Open ID Connect Bearer Token</strong> authentication method. This validates a caller&#39;s JWT access token against an identity provider before the endpoint runs.</p><p>Use this when a host application (for example AireFrame) already has a <strong>user</strong> access token and needs to:</p><ul><li>Secure an AireGlu endpoint with that token</li><li>Make the validated token available inside the endpoint execution pipeline</li></ul><p>This authentication type is named <strong>Open ID Connect Bearer Token</strong> in the endpoint editor. It is separate from <a href="/docs/endpoint-authentication/client-credentials.html">Client Credentials</a>, which is for server to server application tokens obtained with a client ID and secret, not end user access tokens from a host application.</p><p>This is also separate from the <a href="/docs/endpoints/jwt.html">JWT Task</a>, which <strong>generates</strong> tokens inside an endpoint. Open ID Connect Bearer Token authentication <strong>validates inbound</strong> tokens from callers.</p><h2 id="configuring-an-endpoint" tabindex="-1">Configuring an endpoint <a class="header-anchor" href="#configuring-an-endpoint" aria-label="Permalink to &quot;Configuring an endpoint&quot;">​</a></h2><p>In the endpoint editor, open <strong>Authentication</strong> and add <strong>Open ID Connect Bearer Token</strong>.</p><table><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><strong>Authority</strong></td><td>Yes</td><td>Issuer base URL for the identity provider (for example the AireIdentity authority at <code>https://identity.aireinnovate.com</code>). You must enter this value; it is not pre-filled. AireGlu loads signing keys from <code>{authority}/.well-known/openid-configuration</code>.</td></tr><tr><td><strong>Audiences</strong></td><td>Yes</td><td>Comma separated list of allowed <code>aud</code> claim values. The token must match <strong>any one</strong> value in the list.</td></tr><tr><td><strong>Scopes</strong></td><td>No</td><td>Comma separated list of scopes the token must include. When set, the token must contain <strong>all</strong> listed scopes. When left empty, no scope claim is required.</td></tr></tbody></table><p>Authority, audiences, and scopes support <a href="/docs/getting-started/variables.html">variables</a> using the same mapping syntax as other authentication fields.</p><p>If multiple authentication methods are configured on an endpoint, <strong>all</strong> of them must pass.</p><h2 id="how-callers-pass-a-token" tabindex="-1">How callers pass a token <a class="header-anchor" href="#how-callers-pass-a-token" aria-label="Permalink to &quot;How callers pass a token&quot;">​</a></h2><p>AireGlu resolves the token in this order:</p><ol><li><strong><code>Authorization: Bearer &lt;token&gt;</code></strong> (preferred)</li><li><strong>Form POST body</strong>, only when the request has a form content type (<code>application/x-www-form-urlencoded</code> or <code>multipart/form-data</code>). AireGlu reads the first non empty value from a field named <strong><code>jwt</code></strong>, or <strong><code>token</code></strong> if <code>jwt</code> is not present (case insensitive field names).</li></ol><p>Query string tokens are <strong>not</strong> accepted. Passing <code>?jwt=...</code> on the URL will not authenticate the request.</p><h3 id="bearer-header-api-and-server-to-server-calls" tabindex="-1">Bearer header (API and server to server calls) <a class="header-anchor" href="#bearer-header-api-and-server-to-server-calls" aria-label="Permalink to &quot;Bearer header (API and server to server calls)&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> https://glu-api.example.com/my-tenant/my-endpoint</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer eyJhbGciOiJSUzI1NiIs...</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;example&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;payload&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Use this for direct API calls, background services, and follow up requests from page JavaScript after the initial load.</p><h3 id="form-body-iframe-handoff" tabindex="-1">Form body (iframe handoff) <a class="header-anchor" href="#form-body-iframe-handoff" aria-label="Permalink to &quot;Form body (iframe handoff)&quot;">​</a></h3><p>Browsers cannot set custom headers on an iframe&#39;s initial navigation. Host applications such as AireFrame can instead <strong>POST</strong> the access token in the form body so it does not appear in the URL, server access logs, or Referer headers.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">form</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;aireglu-handoff&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> method</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;POST&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://glu-api.example.com/my-tenant/my-endpoint&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;aireglu-frame&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">input</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;hidden&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;jwt&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ACCESS_TOKEN_HERE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">form</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;aireglu-frame&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;document.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getElementById</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;aireglu-handoff&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">submit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>The host page must submit the form to load the iframe. Setting <code>src</code> on the iframe directly will not send the token in the form body.</p><p>The field name may be <strong><code>jwt</code></strong> or <strong><code>token</code></strong>. Both are treated the same.</p><p>If both an <code>Authorization</code> header and a form field are present, the header is used. If the header value is invalid, AireGlu does <strong>not</strong> fall back to the form field.</p><p>AireFrame widgets that embed AireGlu endpoints should POST the user&#39;s access token in a <code>jwt</code> or <code>token</code> form field rather than putting it on the query string. This keeps long lived credentials out of URL based logging.</p><h2 id="token-validation" tabindex="-1">Token validation <a class="header-anchor" href="#token-validation" aria-label="Permalink to &quot;Token validation&quot;">​</a></h2><p>After a token is resolved, AireGlu validates it against the configured identity provider:</p><ol><li>Fetches Open ID Connect metadata from <code>{authority}/.well-known/openid-configuration</code> (cached per authority).</li><li>Resolves signing keys from the metadata document or JWKS endpoint.</li><li>Validates signature, issuer (must match the configured <strong>Authority</strong>), expiry, and audience.</li><li>When <strong>Scopes</strong> are configured on the endpoint, verifies the token&#39;s <code>scope</code> claim contains every required scope (case sensitive). Scope values may appear as multiple claims or as a single space separated string.</li><li>Applies tenant matching for AireIdentity tokens (see below).</li></ol><p>If validation fails, the endpoint returns <strong>401 Unauthorized</strong>.</p><h2 id="identity-providers" tabindex="-1">Identity providers <a class="header-anchor" href="#identity-providers" aria-label="Permalink to &quot;Identity providers&quot;">​</a></h2><h3 id="aireidentity" tabindex="-1">AireIdentity <a class="header-anchor" href="#aireidentity" aria-label="Permalink to &quot;AireIdentity&quot;">​</a></h3><p>When <strong>Authority</strong> is set to AireIdentity (for example <code>https://identity.aireinnovate.com</code>), AireGlu validates the token and checks that it was issued for the same tenant as the endpoint. You must enter the issuer URL yourself; it is not pre-filled.</p><p>Example audience values for AireIdentity tokens often look like <code>api://my-application</code> or another resource identifier registered with the identity provider.</p><h3 id="third-party-identity-providers" tabindex="-1">Third party identity providers <a class="header-anchor" href="#third-party-identity-providers" aria-label="Permalink to &quot;Third party identity providers&quot;">​</a></h3><p>When <strong>Authority</strong> points to an external provider (for example <code>https://login.microsoftonline.com/{tenant}/v2.0</code>), AireGlu validates issuer, signature, lifetime, audience, and optional scopes against that provider&#39;s metadata. <strong>Tenant matching is skipped</strong>. You must enter the correct issuer URL yourself; it is not pre-filled. The endpoint configuration defines which issuer and audiences are trusted.</p><p>Use this when an endpoint must accept tokens from a customer&#39;s own identity provider rather than AireIdentity.</p><h2 id="using-the-token-inside-an-endpoint" tabindex="-1">Using the token inside an endpoint <a class="header-anchor" href="#using-the-token-inside-an-endpoint" aria-label="Permalink to &quot;Using the token inside an endpoint&quot;">​</a></h2><p>After successful authentication, the validated access token is available in the execution pipeline as <strong><code>request.userToken</code></strong>.</p><p>In <a href="/docs/quickstart/liquid.html">Liquid</a> templates:</p><div class="language-liquid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">liquid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Authorization: Bearer {{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">request</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.userToken }}</span></span></code></pre></div><p>Use this to forward the caller&#39;s token to downstream HTTP requests, other AireGlu endpoints, or external APIs that should act on behalf of the same user.</p><p>The token is not automatically added to outbound requests. Reference it explicitly where needed (for example in an HTTP Request task header).</p><p><code>request.userToken</code> contains the full access token. Avoid logging it in usage data, audit output, or HTTP responses unless required.</p><h2 id="comparison-with-other-authentication-methods" tabindex="-1">Comparison with other authentication methods <a class="header-anchor" href="#comparison-with-other-authentication-methods" aria-label="Permalink to &quot;Comparison with other authentication methods&quot;">​</a></h2><table><thead><tr><th>Method</th><th>Typical use</th><th>Token / credential</th></tr></thead><tbody><tr><td><strong>Open ID Connect Bearer Token</strong></td><td>User context calls from host apps and iframes</td><td>JWT access token from an identity provider</td></tr><tr><td><strong>Client Credentials</strong></td><td>Server to server, no user session</td><td>Application access token from AireIdentity</td></tr><tr><td><strong>API Key</strong></td><td>Simple shared secret</td><td>Static key in <code>X-Api-Key</code> header</td></tr></tbody></table><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table><thead><tr><th>Symptom</th><th>Things to check</th></tr></thead><tbody><tr><td>401 with form POST</td><td>Request content type must be form encoded or multipart. JSON bodies with a <code>jwt</code> property are not read for authentication.</td></tr><tr><td>401 with <code>?jwt=</code> on URL</td><td>Query parameters are intentionally ignored. Use Bearer header or form POST.</td></tr><tr><td>401, AireIdentity</td><td>Confirm <strong>Authority</strong> is set to your AireIdentity issuer URL (for example <code>https://identity.aireinnovate.com</code>). Check token <code>aud</code> matches one configured audience, the token tenant matches the endpoint tenant, and required scopes are present.</td></tr><tr><td>401, third party provider</td><td>Confirm the <strong>Authority</strong> URL matches the external provider&#39;s issuer (this is not pre-filled). Check the audience list and that the provider&#39;s signing keys are reachable from AireGlu runtime.</td></tr><tr><td>Token works in header but not iframe</td><td>Ensure the host submits a form POST (not an iframe <code>src</code> URL) before or when loading the iframe; verify the field name is <code>jwt</code> or <code>token</code>.</td></tr></tbody></table>`,47),o=[n];function r(d,h,l,p,c,k){return i(),t("div",null,o)}const m=e(a,[["render",r]]);export{g as __pageData,m as default};
